const fn = new Function(code + "\nreturn { createExplorer };");
const { createExplorer } = fn();
const ex = createExplorer([{ id: "a", score: 1 }, { id: "b", score: 2 }]);
if (ex.byId("b")?.score !== 2) throw new Error("byId('b') should return the record with id 'b'.");
if (ex.byId("zz") !== null) throw new Error("An unknown id must return null, not undefined.");

const fn = new Function(code + "\nreturn { createExplorer };");
const { createExplorer } = fn();
const ex = createExplorer([{ id: 1, score: 1 }, { id: 2, score: 2 }, { id: 3, score: 3 }]);
if (ex.count() !== 3) throw new Error("count() should report the number of records (3 here).");

const fn = new Function(code + "\nreturn { createExplorer };");
const { createExplorer } = fn();
const recs = [
  { id: 1, score: 5 },
  { id: 2, score: 9 },
  { id: 3, score: 5 },
  { id: 4, score: 7 },
];
const ex = createExplorer(recs);
const top2 = ex.top(2);
if (top2.length !== 2 || top2[0].id !== 2 || top2[1].id !== 4) throw new Error("top(2) should be the two highest scores: ids 2 and 4.");
const topAll = ex.top(10);
if (topAll.map((r) => r.id).join(",") !== "2,4,1,3") throw new Error("With ties (both score 5), the earlier record must come first: expected 2,4,1,3.");
